sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var payload = JSON.parse(current.payload.getDisplayValue());

        if (typeof(payload['DETAILS']) != "undefined") {
            var parentSysId;
            var total = payload.DETAILS.length;
            var success = 0;
            for (var i = 0; i < payload.DETAILS.length; i++) {
                var tradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
                tradeCase.addQuery('financial_object.u_ctac_trade_audit_0_order_id_s', payload.DETAILS[i].ORDER_ID);
                tradeCase.addQuery('active', 'true');
                tradeCase.query();
                if (tradeCase.next()) {
                    tradeCase.symphony_response = payload.DETAILS[i].ACTION;
                    tradeCase.symphony_response_by = payload.EMPLOYEE_REFERENCE_NAME;
                    tradeCase.update();
                    var child = new GlideRecord('x_hsb11_mss_smh_child_aggregated_trade_chat_queue');
                    child.addQuery('order_id', payload.DETAILS[i].ORDER_ID);
                    child.query();
                    if (child.next()) {
                        parentSysId = child.getValue('parent');
                        child.symphony_response = payload.DETAILS[i].ACTION;
                        child.symphony_response_by = payload.EMPLOYEE_REFERENCE_NAME;
                        child.actioned = true;
                        child.update();
                    } else {
                        break;
                    }
                    success++;
                }
            }
            var parent = new GlideRecord('x_hsb11_mss_smh_parent_aggregated_trade_chat_queue');
            if (parent.get(parentSysId)) {
                parent.aggregation_status = 'Reponse received';
                parent.update();
            }
            if (total == success) {
                current.status = "Processed";
            } else {
                current.status = "Error";
            }
            current.update();
        } else {

            var mssSymphonyInbound = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
            mssSymphonyInbound.addQuery('number', current.object_id);
            mssSymphonyInbound.query();
            if (mssSymphonyInbound.next()) {
                var tradeCaseTable = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
                tradeCaseTable.addQuery('number', mssSymphonyInbound.parent.number);
                tradeCaseTable.query();
                if (tradeCaseTable.next()) {

                    tradeCaseTable.symphony_response = current.event_status;
                    tradeCaseTable.update();
                }
            }
            current.status = "Processed";
            current.update();
            current.event_status;
        }
    } catch (e) {

        current.status = "Error";
        current.update();
        gs.error("[BR][HSBC-Symphony response update on Case]: " + e.getMessage());
    }

})(current, previous);
